import React from 'react';
import { Outlet, NavLink } from 'react-router-dom';

const TrangChuQuanLy = () => {
    const menuItems = [
        { name: 'Quản lý thông báo', path: 'thong-bao' },
        { name: 'Quản lý cư dân', path: 'cu-dan' },
        { name: 'Quản lý căn hộ', path: 'can-ho' },
        { name: 'Quản lý hoá đơn', path: 'hoa-don' },
        { name: 'Quản lý yêu cầu bảo trì', path: 'bao-tri' },
        { name: 'Quản lý phương tiện', path: 'phuong-tien' },
    ];

    return (
        <div style={styles.container}>
            {/* 1. SIDEBAR (Ảnh 1) */}
            <aside style={styles.sidebar} className="glass-sidebar">
                <div style={styles.logoBox}>
                    <h1 style={styles.logoText}>A&RMS</h1>
                </div>
                <nav style={styles.navStack}>
                    {menuItems.map((item, index) => (
                        <NavLink 
                            key={index} 
                            to={`/dashboard-quan-ly/${item.path}`} 
                            style={({ isActive }) => ({
                                ...styles.navBtn,
                                backgroundColor: isActive ? '#8b5e5e' : 'rgba(255, 255, 255, 0.8)',
                                color: isActive ? '#fff' : '#333',
                                backgroundImage: isActive ? 'none' : "url('../assets/nen_nut_chinh.jpg')",
                                backgroundSize: 'cover'
                            })}
                        >
                            {item.name}
                        </NavLink>
                    ))}
                </nav>
            </aside>

            {/* 2. VÙNG NỘI DUNG CHÍNH */}
            <div style={styles.contentArea}>
                <header style={styles.topHeader} className="glass-sidebar">
                    <span style={{color: '#fff', fontWeight: 'bold'}}>Hệ thống quản trị toà nhà</span>
                    <div style={styles.adminTag}>admin</div>
                </header>

                <main style={styles.mainSlot}>
                    {/* Đây là nơi "Ảnh 2" sẽ hiện ra */}
                    <Outlet /> 
                </main>
            </div>
        </div>
    );
};

const styles = {
    container: { display: 'flex', height: '100vh', padding: '15px', gap: '15px', boxSizing: 'border-box' },
    sidebar: { width: '270px', borderRadius: '30px', display: 'flex', flexDirection: 'column', padding: '20px' },
    logoBox: { height: '80px', display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: '30px' },
    logoText: { color: '#fff', fontSize: '32px', fontWeight: '900', letterSpacing: '2px' },
    navStack: { display: 'flex', flexDirection: 'column', gap: '12px' },
    navBtn: { padding: '15px 20px', borderRadius: '20px', textDecoration: 'none', fontWeight: 'bold', fontSize: '13px', transition: '0.3s' },
    contentArea: { flex: 1, display: 'flex', flexDirection: 'column', gap: '15px' },
    topHeader: { height: '65px', borderRadius: '25px', display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '0 30px' },
    adminTag: { background: 'rgba(255,255,255,0.2)', color: '#fff', padding: '6px 20px', borderRadius: '15px', fontSize: '12px', fontWeight: 'bold' },
    mainSlot: { flex: 1, overflow: 'hidden' }
};

export default TrangChuQuanLy;
